def find_sum(lst):
    """
    Returns the sum of all unique (non-repeated) elements in a list.

    Example:
        [1, 2, 3, 1, 1, 4, 5, 6] -> unique = {1, 2, 3, 4, 5, 6}
                                    sum = 1 + 2 + 3 + 4 + 5 + 6 = 21
    """
    # Use a set to keep only unique elements
    return sum(set(lst))


# Test assertion as given in the problem statement
if __name__ == "__main__":
    assert find_sum([1, 2, 3, 1, 1, 4, 5, 6]) == 21

if __name__ == "__main__":
    print("Test passed!")

