def find_sum(lst):
    """
    Returns the sum of all unique (non-repeated) elements in a list.

    Example:
        [1, 2, 3, 1, 1, 4, 5, 6] -> unique = {1, 2, 3, 4, 5, 6}
                                    sum = 1 + 2 + 3 + 4 + 5 + 6 = 21
    """
    # Use a set to get only the non-repeated (unique) elements
    unique_elements = list(set(lst))

    return sum(unique_elements)


